CREATE TABLE IF NOT EXISTS tourist_places (id BIGSERIAL PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, category TEXT NOT NULL, image_url TEXT NOT NULL DEFAULT '', image_alt TEXT NOT NULL DEFAULT '', tags TEXT[] NOT NULL DEFAULT '{}', description TEXT NOT NULL DEFAULT '', detail TEXT NOT NULL DEFAULT '', quote TEXT NOT NULL DEFAULT '', sort_order INTEGER NOT NULL DEFAULT 0, is_published BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS tourist_places_published_sort_idx ON tourist_places (is_published, sort_order);